INSERT INTO public.site_content(content_key,content_value) VALUES ('about', '{"personal": {"name": "Md. Abu Sufyan", "degree": "Computer Science & Engineering", "university": "Rajshahi University of Engineering & Technology (RUET), Bangladesh"}, "interests": ["Machine Learning", "Deep Learning", "Computer Vision", "Sentiment Analysis", "Time-Series Forecasting", "Predictive Modeling", "Natural Language Processing", "AI for Social Good"], "languages": [{"name": "Bangla", "proficiency": "Native"}, {"name": "English", "proficiency": "Professional Working Proficiency"}], "softSkills": ["Team Leadership", "Technical Communication", "Public Speaking", "Project Planning", "Event Management", "Problem Solving", "Documentation", "Team Collaboration"]}'::jsonb) ON CONFLICT(content_key) DO NOTHING;
INSERT INTO public.site_content(content_key,content_value) VALUES ('achievements', '[{"id": 1, "title": "RUET CSE Graduate", "subtitle": "CGPA 3.60/4.00", "description": "Graduation year 2024; final result published 11 August 2026. Academic session 2020–2021.", "icon": "Trophy", "category": "Academic", "date": "2024", "color": "text-yellow-500"}, {"id": 2, "title": "Research Publications", "subtitle": "2 Conference Papers at ICCiT 2024", "description": "Co-authored papers on Sentiment & Bias Detection in Social Media and Monkeypox Outbreak Prediction using ML models", "icon": "Presentation", "category": "Research", "date": "2024", "color": "text-purple-500"}, {"id": 3, "title": "Leadership Roles", "subtitle": "Former President of Two RUET Clubs", "description": "Former president of RUET IoT Club and RUET Computing Society; now IoT Club Alumni Affairs Advisor and Computing Society alumni member.", "icon": "Users", "category": "Leadership", "date": "2025–2026", "color": "text-blue-500"}, {"id": 4, "title": "AI Instructor & Mentor", "subtitle": "Training at AI Bangladesh", "description": "Conducting hands-on training sessions on ML, Deep Learning, Computer Vision and Data Science for students and professionals", "icon": "Award", "category": "Teaching", "date": "2024-Present", "color": "text-green-500"}, {"id": 5, "title": "Continuing Professional Learning", "subtitle": "Courses, Training & Participation", "description": "Documented learning from Kaggle, Google, Anthropic, Simplilearn SkillUp, Duke/Coursera, UNDP and other providers. Course completions are distinguished from professional credentials.", "icon": "Award", "category": "Certification", "date": "2024-2026", "color": "text-red-500"}, {"id": 6, "title": "Community Impact", "subtitle": "Volunteer & Former HR Officer", "description": "Contributed to VBD, Aachol Foundation, JAAGO Foundation, and Manus Manusher Jonnya Foundation for social welfare", "icon": "Target", "category": "Community", "date": "2021-Present", "color": "text-indigo-500"}, {"id": 7, "title": "Chemistry Olympiad", "subtitle": "Joint 22nd (19) Position · Preliminary Round", "description": "11th Bangladesh Chemistry Olympiad 2020 preliminary round, held 27 August 2021. Competition year and event date are recorded separately.", "icon": "Star", "category": "Competition", "date": "27 August 2021", "color": "text-orange-500"}, {"id": 8, "title": "Industrial Attachment", "subtitle": "BrainStation 23 PLC · 15 Days", "description": "Completed the CSE 4108 industrial attachment in machine learning during March 2025.", "icon": "Code", "category": "Industry", "date": "2025", "color": "text-pink-500"}, {"id": 9, "title": "VBD Service Recognition", "subtitle": "HR Officer · Rajshahi District", "date": "1 January 2026", "description": "Certificate of appreciation for Human Resource Officer service during 2025.", "icon": "Award", "category": "Community", "color": "text-green-500"}, {"id": 10, "title": "FutureNation Recognition", "subtitle": "Campus Volunteer", "date": "16 February 2026", "description": "Recognized for dedication to youth upskilling and community development.", "icon": "Award", "category": "Community", "color": "text-blue-500"}]'::jsonb) ON CONFLICT(content_key) DO NOTHING;
INSERT INTO public.site_content(content_key,content_value) VALUES ('ai_profile', '{"current_roles": "Junior Software Engineer at Scalius Labs (September 2026–Present); Machine Learning & AI Instructor at Artificial Intelligence Bangladesh; Research Assistant at RUET; Alumni Affairs Advisor at RUET IoT Club and Computing Society alumni member since June 2026.", "past_roles": "RUET IoT Club President (February 2025–June 2026); RUET Computing Society President (January–June 2026); Aachol Foundation HR Executive (July 2025–June 2026). BCC Python training is documented for 2026; an ongoing appointment is not confirmed.", "education": "B.Sc. in Computer Science & Engineering at RUET; graduation year 2024, session 2020–2021; result published 11 August 2026.", "projects": "Traffic sign detection with YOLOv8, MobileNet and ResNet; Flutter/Firebase attendance management; SpotSync smart parking and EV charging API using Go, Echo, GORM and PostgreSQL; explainable adversarial intrusion detection using CNN-BiLSTM, IBM ART and SHAP. See Projects for repository links.", "research": "Co-author of two ICCiT 2024 papers: A Cross-Analyzing Approach to Sentiment and Bias Detection in Social Media: Insights from Geopolitical Conflicts; Improving Monkeypox Outbreak Prediction Through Time-Series Forecasting with Machine Learning Models (XGBoost/LSTM/Prophet).", "skills": "Python, C, C++, JavaScript, SQL, Dart; TensorFlow, PyTorch, Scikit-learn, Pandas, NumPy; React, Tailwind CSS, Node.js, Laravel; Flutter, Firebase, Git, Docker, Linux.", "certifications": "Course completions include Claude 101, Google GenAI for Educators, Kaggle ML/DL, Duke/Coursera, Ostad, EDGE and UNDP. CAPM preparation is not a PMI certification; CCNA Jumpstart is not a Cisco CCNA certification. See Certifications for verified details.", "contact": "Use the Contact section of this portfolio for engineering work, research collaborations, mentoring or speaking opportunities."}'::jsonb) ON CONFLICT(content_key) DO NOTHING;
