INSERT INTO public.site_content(content_key,content_value) VALUES ('education', '[{"id": 1, "title": "Bachelor of Science in Computer Science & Engineering", "institution": "Rajshahi University of Engineering & Technology (RUET)", "location": "Rajshahi-6204, Bangladesh", "period": "Graduated 2024 · Session 2020–2021", "cgpa": "3.60 / 4.00", "description": "Final result published 11 August 2026. Focused on Machine Learning, Deep Learning, and Computer Vision. Core competencies include algorithms, data structures, operating systems, computer networks, image processing, neural networks, signal processing, computer security, VLSI design, and hardware architecture.", "type": "university"}, {"id": 2, "title": "Higher Secondary Certificate (HSC)", "institution": "Gurudoyal Govt College", "location": "Kishorganj, Bangladesh", "period": "2020", "cgpa": "", "description": "Completed HSC in Science with focus on Mathematics, Physics, Chemistry, Biology, and ICT.", "type": "college"}, {"id": 3, "title": "Secondary School Certificate (SSC)", "institution": "Alhaj Amir Uddin High School", "location": "Kishorganj, Bangladesh", "period": "2018", "cgpa": "", "description": "Completed secondary education with fundamentals in Mathematics, Science, and technology subjects.", "type": "school"}]'::jsonb) ON CONFLICT(content_key) DO NOTHING;
INSERT INTO public.site_content(content_key,content_value) VALUES ('experience', '[{"title": "Junior Software Engineer", "company": "Scalius Labs", "period": "September 2026 – Present", "description": ["Software engineering with AI-assisted development workflows using Codex and Claude."], "location": "Bangladesh", "logo": "/assets/logo/research.jpeg", "website": "", "featured": true}, {"title": "Python Trainer", "company": "Bangladesh Computer Council (BCC), Rajshahi", "logo": "/assets/logo/research.jpeg", "location": "Rajshahi, Bangladesh", "period": "2026", "website": "https://bcc.gov.bd", "description": ["Delivered Python training at Bangladesh Computer Council (BCC), Rajshahi.", "Supported practical programming instruction and learner mentoring."], "featured": true}, {"title": "Machine Learning & AI Instructor", "company": "Artificial Intelligence Bangladesh", "logo": "/assets/logo/aibd.jpeg", "location": "High Tech Park, Silicon Tower, Rajshahi, Bangladesh", "period": "March 2024 – Present", "website": "https://aibd.ai", "description": ["Conducted hands-on training sessions on Machine Learning, Deep Learning, Computer Vision and Data Science for students and professionals", "Designed and delivered course materials covering supervised/unsupervised learning, model evaluation, and deployment workflows", "Mentored learners through practical projects, improving their problem-solving and coding skills in Python and ML frameworks", "Collaborated with AI Bangladesh community initiatives to expand outreach and promote applied AI education in Bangladesh"], "featured": true}, {"title": "Industrial Trainee — Machine Learning", "company": "BrainStation 23 PLC", "logo": "/assets/logo/research.jpeg", "location": "Dhaka, Bangladesh", "period": "March 2025 · 15 days", "website": "", "description": ["Completed the CSE 4108 industrial attachment, gaining exposure to machine learning development and industry workflows.", "Worked with data preprocessing, model training and evaluation during the attachment."], "featured": true}, {"title": "Alumni Affairs Advisor", "company": "RUET IoT Club", "period": "June 2026 – Present", "description": ["Supports the club as Alumni Affairs Advisor after serving as president."], "location": "Bangladesh", "logo": "/assets/logo/research.jpeg", "website": "", "featured": false}, {"title": "Former President & Founding Member", "company": "RUET Computing Society", "logo": "/assets/logo/research.jpeg", "location": "Rajshahi University of Engineering & Technology (RUET), Rajshahi, Bangladesh", "period": "January – June 2026", "website": "https://ruetcs.org", "description": ["Led computing research, innovation and collaborative learning initiatives.", "Organized technology seminars and coordinated student teams.", "Continues as an alumni member from June 2026."], "featured": true}, {"title": "Director, Project Nexus", "company": "RUET IoT Club", "logo": "/assets/logo/iot_club.png", "location": "Rajshahi University of Engineering & Technology (RUET), Rajshahi, Bangladesh", "period": "2025 – Present", "website": "https://ruetiotclub.org", "description": ["Directing a sustainable-engineering initiative integrating IoT hardware and ML-driven analytics for clean-water monitoring", "Designing edge-sensing systems and data pipelines that translate raw water-quality telemetry into actionable insights", "Coordinating cross-disciplinary research, prototype development and stakeholder outreach for environmental impact"], "featured": true}, {"title": "Campus Representative", "company": "FutureNation Volunteer", "logo": "/assets/logo/futurenation.jpeg", "location": "Rajshahi University of Engineering & Technology (RUET), Rajshahi, Bangladesh", "period": "June 2025 – Present", "website": "https://futurenation.gov.bd", "description": ["Organized and facilitated FutureNation programs and workshops within the RUET campus", "Led university-level initiatives to engage students in FutureNation''s skill-building and youth empowerment projects", "Collaborated with FutureNation teams and partner organizations to ensure impactful program execution"]}, {"title": "Former President", "company": "RUET IoT Club", "logo": "/assets/logo/iot_club.png", "location": "Rajshahi University of Engineering & Technology (RUET), Rajshahi, Bangladesh", "period": "February 2025 – June 2026", "website": "https://ruetiotclub.org", "description": ["Organized workshops and events on IoT and smart technologies", "Coordinated technical sessions focusing on innovation, automation, and advanced IoT applications", "Collaborated with student bodies to enhance hands-on learning and technical collaboration", "Previously served as Joint Organizing Secretary; dates not specified in source CVs."]}, {"title": "Research Assistant", "company": "Machine Learning Research Group", "logo": "/assets/logo/research.jpeg", "location": "Department of Computer Science & Engineering, RUET, Rajshahi-6204, Bangladesh", "period": "July 2024 – Present", "supervisor": "Assistant Prof. S. M. Mahedy Hasan", "website": "", "description": ["Engaged in machine learning research with a focus on sentiment analysis and predictive modeling", "Co-authored papers accepted at ICCiT 2024 on social media bias and time-series forecasting", "Preprocessed datasets and implemented ML/DL models for research experiments", "Conducted research on sentiment analysis and time-series forecasting"], "featured": true}, {"title": "Former Executive Member, Human Resource Management", "company": "Aachol Foundation", "logo": "/assets/logo/research.jpeg", "location": "Dhaka, Bangladesh", "period": "July 2025 – June 2026", "website": "https://aacholfoundation.com", "description": ["Supported human resource activities, including volunteer onboarding and member coordination", "Assisted in organizing awareness campaigns and mental health support initiatives", "Collaborated with the HR team to enhance operational efficiency in community-driven projects"]}, {"title": "Human Resource Officer", "company": "Volunteer for Bangladesh (VBD)", "logo": "/assets/logo/futurenation.jpeg", "location": "Rajshahi District, Bangladesh", "period": "January – December 2025", "website": "https://vbd.com.bd", "description": ["Led environmental cleaning drives, tree plantation campaigns, and community awareness programs aligned with SDGs", "Managed volunteer teams and coordinated with local authorities and NGOs for social impact initiatives", "Organized campaigns on public health and environmental awareness"]}, {"title": "Campus Volunteer", "company": "Manus Manusher Jonnya Foundation", "logo": "/assets/logo/research.jpeg", "location": "RUET Campus, Rajshahi, Bangladesh", "period": "January 2021 – Present", "website": "", "description": ["Contributed to disaster relief, education, and youth empowerment initiatives", "Organized community outreach programs and awareness campaigns", "Collaborated with volunteer teams on social welfare projects"]}, {"title": "Committee Member", "company": "Volunteer for Bangladesh (JAAGO Foundation)", "logo": "/assets/logo/futurenation.jpeg", "location": "Rajshahi, Bangladesh", "period": "June 2023 – Present", "website": "", "description": ["Organized public health, environmental campaigns, and youth development projects", "Participated in community service initiatives aligned with sustainable development goals", "Engaged in educational programs and awareness drives"]}, {"title": "Youth Trainer — Ekannor Jaagoron", "company": "JAAGO Foundation Trust", "period": "December 2025", "description": ["Participated as a trainer in the divisional youth training session on civic awareness and youth empowerment."], "location": "Bangladesh", "logo": "/assets/logo/research.jpeg", "website": "", "featured": false}, {"title": "Independent Teacher & Course Instructor", "company": "Academic & Programming Instruction", "period": "Dates not specified", "description": ["Taught Mathematics, Physics, Chemistry and ICT across school, admission and university levels.", "Delivered programming and web development instruction."], "location": "Bangladesh", "logo": "/assets/logo/research.jpeg", "website": "", "featured": false}]'::jsonb) ON CONFLICT(content_key) DO NOTHING;
INSERT INTO public.site_content(content_key,content_value) VALUES ('faq', '{"categories": [{"name": "About Me", "questions": [{"q": "What is your educational background?", "a": "I graduated in Computer Science & Engineering from RUET in 2024 with a final CGPA of 3.60/4.00 (session 2020–2021). The result was published on 11 August 2026."}, {"q": "What are your main technical interests?", "a": "My main interests include Machine Learning, Deep Learning, Computer Vision, Sentiment Analysis, Time-Series Forecasting, NLP, and AI for Social Good."}, {"q": "What programming languages do you know?", "a": "I''m proficient in Python, C, C++, JavaScript, SQL, and Dart. I also work with frameworks like React, Node.js, Express.js, Laravel, Flutter, TensorFlow, and PyTorch."}]}, {"name": "Experience", "questions": [{"q": "What work experience do you have?", "a": "I joined Scalius Labs as Junior Software Engineer in September 2026. I also teach AI/ML at AI Bangladesh and conduct research with the RUET ML Research Group. I completed a 15-day industrial attachment at BrainStation 23 in March 2025 and delivered Python training at BCC in 2026. Since June 2026, I am RUET IoT Club Alumni Affairs Advisor and a RUET Computing Society alumni member, following my former presidencies. My Aachol HR role ended in June 2026."}, {"q": "What projects have you worked on?", "a": "Key projects include a Traffic Sign Detection System (YOLOv8/MobileNet/ResNet), Sentiment Analysis & Bias Detection in Social Media, Monkeypox Outbreak Prediction using time-series ML models, an Attendance Management App (Flutter), and various full-stack web applications."}]}, {"name": "Skills & Certifications", "questions": [{"q": "What certifications do you have?", "a": "My documented learning includes Kaggle ML/deep learning, Anthropic Claude 101, Google Generative AI for Educators, Duke/Coursera mathematics, Simplilearn courses, Flutter and Laravel training, and UNDP courses. The CAPM and CCNA-related entries are course completions, not PMI or Cisco professional certifications. See the credential catalogue for details."}, {"q": "What are your core technical skills?", "a": "Machine Learning & AI (TensorFlow, PyTorch, Scikit-learn, Pandas, NumPy), Web Development (React, Node.js, Express.js, Laravel), Mobile Development (Flutter/Dart), Hardware Design (Verilog, HDL), and Database Management (MySQL, MongoDB, Firebase)."}]}, {"name": "Contact & Collaboration", "questions": [{"q": "How can I contact you?", "a": "You can reach me via email at abusufyan.cse20@gmail.com or phone at +880 1580 352238. I''m also active on LinkedIn (md-abu-sufyan) and GitHub (sufyan-github)."}, {"q": "Are you available for projects or collaboration?", "a": "Yes! I''m open to research collaborations, AI/ML consulting, technical mentoring, speaking engagements, and full-time opportunities. Feel free to reach out through the contact form or email."}, {"q": "What is your location?", "a": "I''m based in Rajshahi, Bangladesh."}]}], "systemPrompt": "You assist visitors to Md. Abu Sufyan’s portfolio. Use only documented profile information. RUET CSE graduate, graduation year 2024, CGPA 3.60/4.00, result published 11 August 2026. Junior Software Engineer at Scalius Labs since September 2026; AI Bangladesh instructor and RUET research assistant. Former RUET IoT Club and Computing Society president; now IoT Alumni Affairs Advisor and Computing Society alumni member from June 2026. Former Aachol HR executive (ended June 2026). Two ICCiT 2024 papers. Distinguish course completions, participation and professional certification. Do not invent dates, metrics, links or achievements. Direct uncertain questions to the contact section."}'::jsonb) ON CONFLICT(content_key) DO NOTHING;
INSERT INTO public.site_content(content_key,content_value) VALUES ('gallery', '{"title": "Gallery & Events", "subtitle": "Moments from hackathons, workshops, and tech community events", "events": [{"id": "ev00", "title": "Machine Learning Instructional Session - Varendra University", "description": "Conducted a hands-on workshop on Machine Learning and Artificial Intelligence as ML Instructor from AI Bangladesh, in collaboration with the Department of CSE, Varendra University. Received Token of Appreciation for delivering practical ML training sessions.", "date": "October 30, 2025", "location": "Department of CSE, Varendra University, Rajshahi", "category": "Machine Learning", "images": ["/gallery/vu-ml-workshop-1.jpg", "/gallery/vu-ml-workshop-2.jpg", "/gallery/vu-ml-workshop-3.jpg", "/gallery/vu-ml-workshop-4.jpg", "/gallery/vu-ml-workshop-5.jpg", "/gallery/vu-ml-workshop-6.jpg"]}, {"id": "ev01", "title": "ICCiT 2024 Conference", "description": "Presented two research papers on sentiment analysis and health analytics at the International Conference on Computer and Information Technology", "date": "December 2024", "location": "Cox''s Bazar, Bangladesh", "category": "Conference", "images": ["/gallery/iccit-2024-1.jpg", "/gallery/iccit-2024-2.jpg", "/gallery/iccit-2024-3.jpg"]}, {"id": "ev02", "title": "Machine Learning Fundamentals Workshop - RUET", "description": "Conducted hands-on workshop on Machine Learning fundamentals and practical implementation for students", "date": "November 2024", "location": "RUET Campus", "category": "Machine Learning", "images": ["/gallery/ml-workshop-1.jpg", "/gallery/ml-workshop-2.jpg", "/gallery/ml-workshop-3.jpg"]}, {"id": "ev03", "title": "IoT Project Exhibition", "description": "Showcased IoT-based smart solutions at the university tech fair", "date": "October 2024", "location": "RUET Tech Fair", "category": "Exhibition", "images": ["/gallery/iot-expo-1.jpg", "/gallery/iot-expo-2.jpg", "/gallery/iot-expo-3.jpg"]}, {"id": "ev04", "title": "Hackathon Participation", "description": "Team collaboration on AI-powered solutions at the regional hackathon", "date": "September 2024", "location": "Dhaka, Bangladesh", "category": "Hackathon", "images": ["/gallery/hackathon-1.jpg", "/gallery/hackathon-2.jpg", "/gallery/hackathon-3.jpg"]}, {"id": "ev05", "title": "Tree Plantation Drive", "description": "Actively participating in a campus-wide tree plantation drive to promote environmental sustainability and community engagement.", "date": "August 2024", "location": "Campus Green initiative", "category": "Environmental", "images": ["/gallery/tree-plantation-1.jpg", "/gallery/tree-plantation-2.jpg", "/gallery/tree-plantation-3.jpg", "/gallery/tree-plantation-4.jpg", "/gallery/tree-plantation-5.jpg"]}, {"id": "ev06", "title": "Pedal for Planet", "description": "Participated in the ''Pedal for Planet'' cycling event to raise awareness about environmental issues and promote sustainable transportation.", "date": "November 2024", "location": "Rajshahi, Bangladesh", "category": "Environmental", "images": ["/gallery/pedal-for-planet-1.jpg", "/gallery/pedal-for-planet-2.jpg", "/gallery/pedal-for-planet-3.jpg"]}, {"id": "ev07", "title": "VBD Volunteers Meetup & Great Kindness Day", "description": "Join the Great Kindness Day celebration and volunteer meetup with the VBD (Volunteer for Bangladesh) team to discuss social impact projects.", "date": "February 2025", "location": "VBD Regional Office", "category": "Social", "images": ["/gallery/vbd-volunteers-1.jpg", "/gallery/vbd-volunteers-2.jpg"]}, {"id": "ev08", "title": "Machine Learning Session - RUET Computing Society", "description": "Instructional session on Machine Learning and AI conducted for the RUET Computing Society, focusing on real-world applications and engineering fundamentals.", "date": "March 2025", "location": "RUET Computing Society Hall", "category": "Machine Learning", "images": ["/gallery/ruet-ml-session-1.jpg", "/gallery/ruet-ml-session-2.jpg", "/gallery/ruet-ml-session-3.jpg"]}, {"id": "ev09", "title": "Members Orientation - RUET Computing Society", "description": "Presided over the Members Orientation program for the RUET Computing Society. Welcomed new members and shared the vision for technological growth and community building specialized in programming and AI.", "date": "April 2025", "location": "RUET Cafeteria / Auditorium", "category": "Orientation", "images": ["/gallery/ruet-cs-orientation-1.jpg", "/gallery/ruet-cs-orientation-2.jpg", "/gallery/ruet-cs-orientation-3.jpg", "/gallery/ruet-cs-orientation-4.jpg", "/gallery/ruet-cs-orientation-5.jpg"]}]}'::jsonb) ON CONFLICT(content_key) DO NOTHING;
