INSERT INTO public.site_content(content_key,content_value) VALUES ('projects', '[{"id": "p07", "title": "Explainable AI for Adversarial Intrusion Detection", "description": "Undergraduate thesis: Explaining the Attack Surface — XAI-driven defense against adversarial perturbations in deep learning-based intrusion detection. Explored a CNN-BiLSTM detector, FGSM/PGD/C&W attacks through IBM ART, SHAP explanations and an interactive defense visualizer.", "technologies": ["Python", "CNN-BiLSTM", "SHAP", "IBM ART"], "project_type": "AI/ML", "year": "Undergraduate thesis", "featured": true, "github_url": "", "demo_url": "", "image_url": "/projects/p07.svg", "impact": []}, {"id": "p08", "title": "SpotSync — Smart Parking & EV Charging API", "description": "Smart parking and EV charging REST API built with Go, Echo v4, GORM and PostgreSQL. Applied STRIDE and DREAD threat modelling in a security coursework case study.", "technologies": ["Go", "Echo v4", "GORM", "PostgreSQL", "STRIDE", "DREAD"], "project_type": "Web Development", "year": "Academic project", "featured": true, "github_url": "", "demo_url": "", "image_url": "/projects/p08.svg", "impact": []}, {"id": "p09", "title": "Attendance Management App", "description": "Mobile attendance application with course selection, authentication and attendance history.", "technologies": ["Flutter", "Dart", "Firebase Auth", "Realtime Database", "Riverpod"], "project_type": "Mobile Development", "year": "2024", "featured": true, "github_url": "", "demo_url": "", "image_url": "/projects/p09.svg", "impact": []}, {"id": "p10", "title": "Project NEXUS — Water-Quality Monitoring", "description": "IoT water-quality monitoring initiative involving sensing, data acquisition and prototype development with RUET IoT Club.", "technologies": ["IoT", "Sensors", "Data Acquisition"], "project_type": "IoT", "year": "2025", "featured": true, "github_url": "", "demo_url": "", "image_url": "/projects/p10.svg", "impact": []}, {"id": "p11", "title": "EcoHomeAI — Early-Stage Venture", "description": "Founder and technical lead of an early-stage smart-home and energy-management venture, focused on AI, IoT and prototyping.", "technologies": ["IoT", "AI", "Prototyping"], "project_type": "IoT", "year": "2025", "featured": false, "github_url": "", "demo_url": "", "image_url": "/projects/p11.svg", "impact": []}, {"id": "p01", "title": "Traffic Sign Detection System", "description": "Traffic-sign recognition project using deep learning and a Flask web interface. Includes image preprocessing, model experimentation and prediction display.", "impact": [], "technologies": ["Python", "YOLOv8", "MobileNet", "ResNet", "Flask", "OpenCV"], "project_type": "AI/ML", "year": "2025", "featured": true, "github_url": "", "demo_url": "", "image_url": ""}, {"id": "p02", "title": "Gemini Health AI Assistant", "description": "Experimental wellness application integrating the Gemini API with a Streamlit interface to explore personalized health guidance.", "impact": [], "technologies": ["Python", "Streamlit", "Gemini API", "Data Analysis"], "project_type": "AI/ML", "year": "2024", "featured": true, "github_url": "https://github.com/sufyan-github/Gemini-Health-App", "demo_url": "", "image_url": "/projects/p02.svg"}, {"id": "p03", "title": "Medical Chatbot (RAG)", "description": "In-development medical question-answering project exploring retrieval-augmented generation with LangChain, embeddings and a vector store in a modular Python codebase.", "impact": [], "technologies": ["Python", "LangChain", "Pinecone", "Flask", "NLP"], "project_type": "AI/ML", "year": "In development", "featured": true, "github_url": "https://github.com/sufyan-github/end-to-end-medical-chatbot", "demo_url": "", "image_url": "/projects/p03.svg"}, {"id": "p04", "title": "FoodHub — Food Delivery Platform", "description": "Full-stack food ordering project with authentication, order management and a provider dashboard, built with React, Node.js, Express and MongoDB.", "impact": [], "technologies": ["Node.js", "Express", "MongoDB", "React", "TailwindCSS"], "project_type": "Web Development", "year": "2024", "featured": true, "github_url": "https://github.com/sufyan-github/foodhub-complete-project", "demo_url": "", "image_url": "/projects/p04.svg"}, {"id": "p05", "title": "Vehicle Rental REST API", "description": "Vehicle-rental backend project in Go with PostgreSQL, API documentation and authentication.", "impact": [], "technologies": ["Go", "PostgreSQL", "React", "TailwindCSS", "Swagger"], "project_type": "Web Development", "year": "2024", "featured": false, "github_url": "https://github.com/sufyan-github/go-api-vehicle_rental", "demo_url": "", "image_url": "/projects/p05.svg"}, {"id": "p06", "title": "EduBridge — Learning Platform", "description": "Learning platform project using React and Laravel, with course enrolment, progress tracking and an admin interface.", "impact": [], "technologies": ["React", "PHP", "Laravel", "MySQL", "TailwindCSS"], "project_type": "Web Development", "year": "2023", "featured": false, "github_url": "https://github.com/sufyan-github/EduBridge", "demo_url": "", "image_url": "/projects/p06.svg"}, {"id": "p12", "title": "Verilog HDL & Processor Design", "description": "Academic laboratory and project work: simulated combinational and sequential modules including multiplexers, registers, counters and finite-state machines. Explored instruction-set, datapath and control-unit design, comparing simulation waveforms with expected logic.", "technologies": ["Verilog", "Digital Logic", "Computer Architecture", "Simulation"], "project_type": "Hardware", "year": "Academic coursework", "featured": false, "github_url": "", "demo_url": "", "image_url": "/projects/p12.svg", "impact": []}]'::jsonb) ON CONFLICT(content_key) DO NOTHING;
INSERT INTO public.site_content(content_key,content_value) VALUES ('publications', '[{"title": "A Cross-Analyzing Approach to Sentiment and Bias Detection in Social Media: Insights from Geopolitical Conflicts", "conference": "ICCiT 2024", "location": "Cox''s Bazar, Bangladesh", "year": "2024", "type": "Conference Paper", "problem": "During geopolitical conflicts, social-media discourse is contaminated by sentiment polarisation and systemic bias, making impartial situational awareness extremely difficult.", "methodology": "Compared BERT and BiLSTM approaches for sentiment and bias detection in social-media discourse about geopolitical conflicts, using WordPiece and GloVe representations.", "impact": "The paper reports comparative results for sentiment classification and bias detection, highlighting the different strengths of the two approaches.", "description": "Cross-analysing pipeline for sentiment and bias in geopolitical social-media discourse — surfacing measurable bias signals during conflict events.", "keywords": ["Sentiment Analysis", "Bias Detection", "Social Media", "Machine Learning", "NLP"], "paperUrl": "", "conferenceUrl": ""}, {"title": "Improving Monkeypox Outbreak Prediction Through Time-Series Forecasting with Machine Learning Models", "conference": "ICCiT 2024", "location": "Cox''s Bazar, Bangladesh", "year": "2024", "type": "Conference Paper", "problem": "Public-health agencies needed earlier, more reliable forecasts of Monkeypox outbreak trajectories to plan response and allocation.", "methodology": "Compared XGBoost, LSTM and Prophet on monkeypox death time-series data from 2019–2023, with lag and rolling-window features.", "impact": "The study reports the lowest mean squared error among the compared models for Prophet (0.4175), within its experimental setup.", "description": "Comparative time-series forecasting of monkeypox deaths using XGBoost, LSTM and Prophet.", "keywords": ["Time-Series Forecasting", "XGBoost", "LSTM", "Prophet", "Healthcare Analytics"], "paperUrl": "", "conferenceUrl": ""}]'::jsonb) ON CONFLICT(content_key) DO NOTHING;
