Leadership", "title": "President — RUET IoT Club · Director — Project Nexus", "org": "RUET", "description": "Led RUET IoT Club and contributed to Project NEXUS water-quality monitoring prototypes.", "icon": "crown"}, {"year": "2026", "phase": "National Impact", "title": "Python Trainer", "org": "Bangladesh Computer Council, Rajshahi", "description": "Delivered Python instruction and practical learner mentoring.", "icon": "sparkles"}, {"year": "2026", "phase": "Career", "title": "Junior Software Engineer", "org": "Scalius Labs", "description": "Joined in September 2026. Also serves as RUET IoT Club Alumni Affairs Advisor and RUET Computing Society alumni member.", "icon": "target"}]'::jsonb) ON CONFLICT(content_key) DO NOTHING;
